// api_src/index.ts
var isInitialized = false;
var initPromise = null;
async function ensureDb() {
  if (isInitialized) return;
  if (!initPromise) {
    initPromise = (async () => {
      try {
        console.log("[Vercel Serverless] Initializing database...");
        await initDb();
        await runMigrations();
        await runSeed().catch(() => {
        });
        isInitialized = true;
        console.log("[Vercel Serverless] Database ready.");
      } catch (err2) {
        console.error("[Vercel Serverless] Database initialization failure:", err2);
      }
    })();
  }
  await initPromise;
}
async function handler(req, res) {
  if (!req.socket) {
    req.socket = { remoteAddress: "127.0.0.1" };
  } else if (!req.socket.remoteAddress) {
    req.socket.remoteAddress = req.headers["x-forwarded-for"]?.split(",")[0]?.trim() || "127.0.0.1";
  }
  await ensureDb();
  const queryPath = req.query?.path;
  if (queryPath) {
    const subpath = Array.isArray(queryPath) ? queryPath.join("/") : queryPath;
    const cleanSubpath = subpath.replace(/^\/+/, "");
    const qIndex = req.url.indexOf("?");
    const existingParams = new URLSearchParams(qIndex !== -1 ? req.url.slice(qIndex) : "");
    existingParams.delete("path");
    const qs = existingParams.toString();
    req.url = `/api/${cleanSubpath}${qs ? "?" + qs : ""}`;
  } else if (req.headers?.["x-forwarded-uri"] && req.headers["x-forwarded-uri"].startsWith("/api")) {
    req.url = req.headers["x-forwarded-uri"];
  } else if (req.headers?.["x-matched-path"] && req.headers["x-matched-path"] !== "/api" && req.headers["x-matched-path"] !== "/api/" && !req.headers["x-matched-path"].includes("index.js")) {
    req.url = req.headers["x-matched-path"];
  } else if (req.url && (req.url.startsWith("/api/index.js") || req.url.startsWith("/api/[...path]") || req.url === "/api/index")) {
    const orig = req.originalUrl;
    if (orig && orig.startsWith("/api") && !orig.includes("index.js")) {
      req.url = orig;
    }
  } else if (!req.url.startsWith("/api")) {
    req.url = `/api${req.url.startsWith("/") ? req.url : "/" + req.url}`;
  }
  if (req.method === "OPTIONS") {
    res.setHeader("Access-Control-Allow-Origin", "*");
    res.setHeader("Access-Control-Allow-Methods", "GET, POST, PUT, PATCH, DELETE, OPTIONS");
    res.setHeader("Access-Control-Allow-Headers", "Content-Type, Authorization, x-order-token, idempotency-key");
    return res.status(204).end();
  }
  return app(req, res);
}
export {
  handler as default
};
